import assert from 'node:assert/strict';let input='';for await(const c of process.stdin)input+=c;const data=JSON.parse(input);const mod=await import('data:text/javascript;base64,'+Buffer.from(data.source).toString('base64'));
const names={complete:'REFRESH_COMPLETE',error:'REFRESH_ERROR',singular:'REFRESH_COMPLETE_WITH_ERROR',plural:'REFRESH_COMPLETE_WITH_ERRORS'};const out={};for(const [key,name] of Object.entries(names)){assert.ok(Object.hasOwn(mod,name),`missing binding ${name}`);out[key]={type:typeof mod[name],value:mod[name]};}assert.deepEqual(JSON.parse(JSON.stringify(out)),JSON.parse(data.expected));
